from __future__ import annotations

import os
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from senpy.core.analyzer import SenpyAnalyzer


def generate_project_wiki(analyzer: SenpyAnalyzer) -> str:
    """Generates Markdown documentation (Wiki) for the project based on the object model."""
    lines: list[str] = [
        "# Project Documentation (Generated by Senpy)",
        "",
        "> This document was automatically generated from Ren'Py source scripts.",
        "",
    ]

    characters = [v for v in analyzer.variables.values() if v.is_character]

    # 1. Characters
    lines.append("## Characters")
    lines.append("")
    if characters:
        lines.append("| Identifier | Declaration Source |")
        lines.append("| :--- | :--- |")
        for char in sorted(characters, key=lambda x: x.name):
            fname = os.path.basename(char.file_path)
            lines.append(f"| `{char.name}` | `{fname}:{char.line_number}` |")
    else:
        lines.append("_No Character declarations detected._")
    lines.append("")

    # 2. Variables and state (default / define)
    lines.append("## State & Variables")
    lines.append("")

    state_vars = [v for v in analyzer.variables.values() if not v.is_character]

    if state_vars:
        lines.append("| Variable | Type | Kind | Source |")
        lines.append("| :--- | :--- | :--- | :--- |")
        for var in sorted(state_vars, key=lambda x: x.name):
            kind = "Constant (`define`)" if var.is_constant else "Variable (`default`)"
            var_type = var.type_name or "unknown"
            fname = os.path.basename(var.file_path)
            lines.append(f"| `{var.name}` | `{var_type}` | {kind} | `{fname}:{var.line_number}` |")
    else:
        lines.append("_No variables or constants detected._")
    lines.append("")

    # 3. Story endings (Endings)
    lines.append("## Story Endings")
    lines.append("")
    # Endings are labels with a return and no outgoing jumps
    endings = []
    for lbl in sorted(analyzer.labels.values(), key=lambda x: x.name):
        if lbl.name.startswith("_"):
            continue
        if lbl.has_return and not lbl.outgoing_jumps:
            endings.append((lbl.name, os.path.basename(lbl.file_path), lbl.line_number))

    if endings:
        lines.append("| Ending Label | Source Location |")
        lines.append("| :--- | :--- |")
        for name, fname, lnum in endings:
            lines.append(f"| `{name}` | `{fname}:{lnum}` |")
    else:
        lines.append("_No explicit terminal endings detected._")
    lines.append("")

    return "\n".join(lines)
